package com.cdg.ordersupport.security;
import com.cdg.ordersupport.user.*; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtTokenService { private final SecretKey key; public JwtTokenService(@Value("${security.jwt.secret}") String secret){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String create(User u){return Jwts.builder().subject(u.getId().toString()).claim("role",u.getRole().name()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(key).compact();} public Jws<Claims> parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token);} }
